$have = @((npx wrangler kv key list --namespace-id $ns --prefix "context:" --remote 2>$null | Out-String | ConvertFrom-Json) | % { $_.name })
$hit = @($have | ? { $want -contains $_ })
if ($hit.Count -eq 0) { "  none found" } else { foreach ($h in $hit) { "  removed " + $h + ": " + ((npx wrangler kv key get --namespace-id $ns $h --remote 2>$null | Out-String).Trim()); npx wrangler kv key delete --namespace-id $ns $h --remote 2>$null | Out-Null } }
foreach ($c in $cats.Keys) { RUN ("REDO " + $final[$test[$c]]) }
